import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"Next Excel Entry Exists","description":"","frontmatter":{"prev":{"text":"Field Action Status Checker","link":"/documentation/field-types/advance/field-action-status-checker"},"next":{"text":"Execute Segment","link":"/documentation/field-types/execute-segment"}},"headers":[],"relativePath":"documentation/field-types/advance/next-excel-entry-exists.md","filePath":"documentation/field-types/advance/next-excel-entry-exists.md","lastUpdated":1791360312000}`),a={name:`documentation/field-types/advance/next-excel-entry-exists.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="next-excel-entry-exists" tabindex="-1">Next Excel Entry Exists <a class="header-anchor" href="#next-excel-entry-exists" aria-label="Permalink to “Next Excel Entry Exists”">​</a></h1><p>The <strong>Next Excel Entry Exists</strong> field type is an advanced control flow field that checks whether another uncompleted row exists in the active uploaded Excel (<code>.xlsx</code>) spreadsheet.</p><p>It functions as a conditional branching checkpoint within your form sequence or segment workflow, returning either a <strong>Success</strong> or <strong>Error</strong> status to direct your automation flow.</p><hr><h2 id="overview" tabindex="-1">Overview &amp; Behavior <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview &amp; Behavior”">​</a></h2><p>Unlike standard form fields that interact with web page inputs or DOM elements, <strong>Next Excel Entry Exists</strong> requires <strong>no field settings or element selectors</strong>. It directly inspects the extension&#39;s internal Excel row index.</p><table tabindex="0"><thead><tr><th>Status</th><th>Condition</th><th>Description</th></tr></thead><tbody><tr><td><strong>Success</strong></td><td>Next row exists</td><td>Another uncompleted record is available in the uploaded <code>.xlsx</code> file.</td></tr><tr><td><strong>Error</strong></td><td>No next row exists</td><td>All records have been processed, or the current entry is the final row in the dataset.</td></tr></tbody></table><p>Because this field type does not have internal configuration inputs, its behavior is controlled through <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a>. You configure specific automated responses for both the <strong>Success</strong> and <strong>Error</strong> channels.</p><hr><h2 id="response-actions" tabindex="-1">Configuring Response Actions <a class="header-anchor" href="#response-actions" aria-label="Permalink to “Configuring Response Actions”">​</a></h2><p>After adding the <strong>Next Excel Entry Exists</strong> field, navigate to the field&#39;s <strong>Response Action Settings</strong> in the settings panel to configure actions for each outcome:</p><h3 id="success-response-action" tabindex="-1">1. Field Success Response Action <a class="header-anchor" href="#success-response-action" aria-label="Permalink to “1. Field Success Response Action”">​</a></h3><p>Executed when the extension verifies that a subsequent Excel row is ready to be processed.</p><ul><li><strong>Go to Next Entry</strong>: Advances the active spreadsheet pointer to the next record.</li><li><strong>Re-Execute Form</strong>: Restarts form automation from the first field to fill the newly selected row.</li><li><strong>Reload Page</strong>: Refreshes the active web page to reset the form inputs before filling the next record.</li><li><strong>Open a URL</strong>: Navigates the browser tab back to the form submission starting page.</li><li><strong>Execute Segment</strong>: Triggers a dedicated modular sub-routine to prepare or process the next record.</li></ul><h3 id="error-response-action" tabindex="-1">2. Field Error Response Action <a class="header-anchor" href="#error-response-action" aria-label="Permalink to “2. Field Error Response Action”">​</a></h3><p>Executed when the extension detects that the final Excel row has been processed and no further data records remain.</p><ul><li><strong>Stop Loop</strong>: Immediately halts the repeating execution loop to conclude automation cleanly.</li><li><strong>Skip Form</strong>: Aborts remaining form steps and moves to the next configured workflow stage.</li><li><strong>Execute Segment</strong>: Runs a completion routine, such as exporting scraped data, sending notifications, or cleaning local storage.</li><li><strong>Open a URL</strong>: Redirects the browser tab to an administrative dashboard, completion summary, or logout page.</li></ul><hr><h2 id="how-to-configure" tabindex="-1">Step-by-Step Configuration <a class="header-anchor" href="#how-to-configure" aria-label="Permalink to “Step-by-Step Configuration”">​</a></h2><ol><li>Open your target <strong>Site Form</strong> or <strong>Segment</strong> in the Excellent Data Filler dashboard.</li><li>Click <strong>Insert Field</strong> (<code>+</code>) to add a new field to your sequence.</li><li>From the <strong>Field Type</strong> dropdown, select <strong>Next Excel Entry Exists</strong> under the <strong>Advance</strong> category.</li><li>Leave the field value and selector inputs empty, as this field type does not require element targeting.</li><li>In the <strong>Response Action Settings</strong> section: <ul><li>Toggle ON <strong>Field Success Response Action</strong> and select your desired action (e.g., <code>Go to Next Entry</code> or <code>Re-Execute Form</code>).</li><li>Toggle ON <strong>Field Error Response Action</strong> and select your exit action (e.g., <code>Stop Loop</code> or <code>Execute Segment</code>).</li></ul></li><li>Click <strong>Save</strong> to confirm your field configuration.</li></ol><hr><h2 id="example-workflow" tabindex="-1">Example Workflow: Automated Multi-Row Batch Loop <a class="header-anchor" href="#example-workflow" aria-label="Permalink to “Example Workflow: Automated Multi-Row Batch Loop”">​</a></h2><p>A common automation scenario involves submitting a web form repeatedly until every row in an uploaded <code>.xlsx</code> spreadsheet is submitted:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Step</th><th>Field Type</th><th>Purpose</th><th>Configuration</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td>Standard Fields (<code>Text</code>, <code>Select</code>, etc.)</td><td>Fill inputs from active Excel row</td><td>Target element selectors with <code>{$Column$}</code> values</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td><strong>Button</strong></td><td>Click form submission button</td><td>Target selector: <code>#submit-button</code></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td><a href="/documentation/field-types/advance/current-entry-as-saved.html"><strong>Current Entry as Saved</strong></a></td><td>Mark active row as completed</td><td>Detect submission confirmation banner</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td><strong>Next Excel Entry Exists</strong></td><td>Verify if more data rows remain</td><td>No selector needed</td></tr><tr><td style="text-align:center;"></td><td>• <em>On Success Response Action</em></td><td>Prepare next row</td><td>Action: <code>Go to Next Entry</code> → <code>Reload Page</code></td></tr><tr><td style="text-align:center;"></td><td>• <em>On Error Response Action</em></td><td>Terminate workflow</td><td>Action: <code>Stop Loop</code></td></tr></tbody></table><p>In this sequence, the form repeatedly processes data rows one by one. Once the final row is saved, <strong>Next Excel Entry Exists</strong> returns <strong>Error</strong>, triggering <code>Stop Loop</code> to halt automation automatically without manual intervention.</p><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Sequence Placement</strong>: Position <strong>Next Excel Entry Exists</strong> after form submission and after marking the record as completed (<a href="/documentation/field-types/advance/current-entry-as-saved.html">Current Entry as Saved</a>), so the status check evaluates only after the active row has been processed.</li><li><strong>Avoid Infinite Loops</strong>: Always ensure that a successful evaluation increments the data index (e.g., using <code>Go to Next Entry</code>) to prevent repeatedly executing against the same row.</li><li><strong>Spreadsheet Requirement</strong>: This field type evaluates records from uploaded <strong>Excel (.xlsx)</strong> workbooks or connected Google Sheets. Ensure a data source is loaded before running batch loops.</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};